// WMO Weather Code to Icon mapping

// WMO Weather Code to Icon mapping
const uint16_t* getWeatherIcon(int weatherCode, int isDay) {
    // Clear sky
    if (weatherCode == 0) {
        return isDay ? icon_sun : icon_moon;
    }
    // Mainly clear, partly cloudy, overcast (1-3)
    if (weatherCode >= 1 && weatherCode <= 3) {
        if (weatherCode <= 2) {
            return isDay ? icon_partly_cloudy_day : icon_partly_cloudy_night;
        }
        return icon_cloudy;
    }
    // Fog (45, 48)
    if (weatherCode == 45 || weatherCode == 48) {
        return icon_fog;
    }
    // Drizzle (51-57) and Rain (61-67, 80-82)
    if ((weatherCode >= 51 && weatherCode <= 57) || 
        (weatherCode >= 61 && weatherCode <= 67) ||
        (weatherCode >= 80 && weatherCode <= 82)) {
        return icon_rain;
    }
    // Snow (71-77, 85-86)
    if ((weatherCode >= 71 && weatherCode <= 77) ||
        (weatherCode >= 85 && weatherCode <= 86)) {
        return icon_snow;
    }
    // Thunderstorm (95-99)
    if (weatherCode >= 95 && weatherCode <= 99) {
        return icon_thunder;
    }
    // Default: cloudy
    return icon_cloudy;
}

// Temperature unit icon getter
const uint16_t* getTempUnitIcon(int isCelsius) {
    return isCelsius ? icon_celsius : icon_fahrenheit;
}

